// ---------- helpers ----------
const box = (txt, x, y, t, size = 16, until, o = {}) => { if (o.pop !== false) SFX("ref:pop", t); return GG.pin(`<div style="background:${o.bg || "#f1eee6"};color:${o.col || "#111"};font-family:Oswald;font-weight:500;letter-spacing:.22em;padding:${(size * 0.2).toFixed(1)}px ${(size * 0.35).toFixed(1)}px ${(size * 0.2).toFixed(1)}px ${(size * 0.6).toFixed(1)}px;font-size:${size}px;white-space:nowrap;box-shadow:0 ${size * 0.1}px ${size * 0.4}px rgba(0,0,0,.6)">${txt}</div>`, x, y, { t, until }); };
const flag = (src, name, x, y, t, until, w = 70) => GG.pin(`<div style="display:flex;flex-direction:column;align-items:center;gap:${Math.round(w * 0.05)}px"><img src="${src}" style="width:${w}px;display:block;border:${Math.max(1, Math.round(w / 40))}px solid #1a1712;box-shadow:0 3px 8px rgba(0,0,0,0.55)"><div class="gg-lbl" style="position:relative;font-size:${Math.round(w * 0.22)}px;color:#f7f3ea;text-shadow:0 2px 4px #000">${name}</div></div>`, x, y, { t, until });
const unit = (id, side, x, y, icon, o = {}) => {
  B.unit({ id, side, x, y, w: o.w || 38, h: o.h || 26, t: o.t, label: o.label });
  K.counter(id, { icon, flag: o.flag || (side === "carth" ? FL.prc : FL.us), size: o.size });
  if (o.until != null) B.hideUnits([id], o.until);
  return id;
};
const scr = (html, css) => { const el = document.createElement("div"); el.style.cssText = "position:absolute;" + css; el.innerHTML = html; scene.insertBefore(el, document.getElementById("credit")); GG.hide(el); return el; };
const slam = (el, t, o = {}) => {
  tl.fromTo(el, { autoAlpha: 0, scale: o.from || 2.2 }, { autoAlpha: 1, scale: 1, duration: 0.24, ease: "power4.in", immediateRender: false }, t);
  SFX(o.sfx || "hit", t + 0.22); K.shake(t + 0.22, o.shake || 5, 0.3);
  if (o.until != null) tl.to(el, { autoAlpha: 0, duration: 0.35 }, o.until);
  return el;
};
const stampHTML = (txt, c, size, rot, sub) => `<div style="transform:rotate(${rot}deg);display:inline-block;text-align:center;font-family:Oswald;font-weight:700;color:${c};border:${Math.max(4, Math.round(size / 9))}px solid ${c};padding:4px 22px 6px;background:rgba(14,12,10,0.72);box-shadow:0 10px 26px rgba(0,0,0,.55);white-space:nowrap"><div style="font-size:${size}px;letter-spacing:0.12em;line-height:1.1">${txt}</div>${sub ? `<div style="font-size:${Math.round(size * 0.3)}px;letter-spacing:0.22em;color:#f7f3ea;margin-top:2px">${sub}</div>` : ""}</div>`;
const stamp = (txt, t, until, o = {}) => slam(scr(stampHTML(txt, o.c || "#e3232f", o.size || 76, o.rot || -5, o.sub), `left:0;right:0;top:${o.top || 640}px;display:flex;justify-content:center;`), t, { until });
const legend = (t, until) => GG.card(`<div style="display:flex;gap:30px;font-size:20px;letter-spacing:0.1em;align-items:center">${[["#2c57b7", "CHINESE"], ["#bc2528", "US / SOUTH KOREAN"]].map(([c, nm]) => `<span><b style="display:inline-block;width:34px;height:7px;background:${c};vertical-align:4px;margin-right:9px;box-shadow:0 0 8px 2px ${c}"></b>${nm}</span>`).join("")}</div>`, "", 34, t, until);
const arrow = (side, pts, t, o = {}) => B.arrow({ side, pts, t, dur: o.dur || 1.2, width: o.w || 9, until: o.until, dash: o.dash });
const walk = (id, pts, t, dur) => { const n = pts.length - 1; pts.slice(1).forEach((q, i) => B.move(id, t + (dur * i) / n, dur / n, q[0], q[1], "none")); };
const shoot = (from, to, t, o = {}) => { K.gun(from[0], from[1], t, { dx: 0, dy: -3 }); GG.arc(from[0], from[1], to[0], to[1], t + 0.05, { dur: o.dur || 0.7, width: 2.2, h: o.h || 24, impact: false }); K.impact(to[0], to[1], t + 0.75, { r: o.r || 9, puffs: 2 }); };
const note = (txt, x, y, t, until) => { SFX("static", t); return GG.pin(`<div style="font-family:Oswald;font-weight:700;font-size:15px;letter-spacing:.2em;color:#dfe9ff;text-shadow:0 0 8px #6f9bff,0 2px 3px #000">&#9834; ${txt}</div>`, x, y, { t, until, pop: true }); };

